function parseDuration(input: string): number {
  if (input.length === 0) {
    throw new Error("Invalid duration: empty string");
  }

  const regex = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;
  const match = input.match(regex);

  if (!match || match[0] !== input) {
    throw new Error(`Invalid duration: "${input}"`);
  }

  const [, h, m, s] = match;

  if (h === undefined && m === undefined && s === undefined) {
    throw new Error(`Invalid duration: "${input}"`);
  }

  const hours = h !== undefined ? parseInt(h, 10) : 0;
  const minutes = m !== undefined ? parseInt(m, 10) : 0;
  const seconds = s !== undefined ? parseInt(s, 10) : 0;

  return hours * 3600 + minutes * 60 + seconds;
}
