function compareSemver(a: string, b: string): -1 | 0 | 1 {
  function parse(v: string) {
    const buildStripped = v.split('+')[0];
    const [corePart, ...preRelParts] = buildStripped.split('-');
    const preRelease = preRelParts.join('-');
    const corePieces = corePart.split('.');

    if (corePieces.length !== 3) throw new Error(`Invalid semver: "${v}"`);

    const [major, minor, patch] = corePieces.map((part) => {
      if (!/^\d+$/.test(part)) throw new Error(`Invalid semver: "${v}"`);
      if (part.length > 1 && part[0] === '0') throw new Error(`Invalid semver (leading zero): "${v}"`);
      return parseInt(part, 10);
    });

    const preReleaseIdentifiers: Array<string | number> = preRelease
      ? preRelease.split('.').map((id) => {
          if (id === '') throw new Error(`Invalid semver (empty pre-release identifier): "${v}"`);
          if (/^\d+$/.test(id)) {
            if (id.length > 1 && id[0] === '0') throw new Error(`Invalid semver (leading zero in pre-release): "${v}"`);
            return parseInt(id, 10);
          }
          if (!/^[0-9A-Za-z-]+$/.test(id)) throw new Error(`Invalid semver (invalid pre-release identifier): "${v}"`);
          return id;
        })
      : [];

    return { major, minor, patch, preReleaseIdentifiers, hasPreRelease: preRelease !== '' };
  }

  function compareIdentifiers(x: string | number, y: string | number): -1 | 0 | 1 {
    if (typeof x === 'number' && typeof y === 'number') {
      return x < y ? -1 : x > y ? 1 : 0;
    }
    if (typeof x === 'number') return -1;
    if (typeof y === 'number') return 1;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
  }

  const pa = parse(a);
  const pb = parse(b);

  for (const field of ['major', 'minor', 'patch'] as const) {
    if (pa[field] < pb[field]) return -1;
    if (pa[field] > pb[field]) return 1;
  }

  if (pa.hasPreRelease && !pb.hasPreRelease) return -1;
  if (!pa.hasPreRelease && pb.hasPreRelease) return 1;
  if (!pa.hasPreRelease && !pb.hasPreRelease) return 0;

  const aIds = pa.preReleaseIdentifiers;
  const bIds = pb.preReleaseIdentifiers;
  const len = Math.min(aIds.length, bIds.length);

  for (let i = 0; i < len; i++) {
    const cmp = compareIdentifiers(aIds[i], bIds[i]);
    if (cmp !== 0) return cmp;
  }

  if (aIds.length < bIds.length) return -1;
  if (aIds.length > bIds.length) return 1;
  return 0;
}
