function buildOrder(deps: Record<string, string[]>): string[] {
  // Collect all packages
  const all = new Set<string>();
  for (const [pkg, requires] of Object.entries(deps)) {
    all.add(pkg);
    for (const r of requires) all.add(r);
  }

  // Build adjacency: edges[x] = packages that depend on x (reverse)
  // indegree[x] = number of dependencies x still needs
  const indegree = new Map<string, number>();
  const dependents = new Map<string, string[]>(); // x -> list of pkgs that depend on x

  for (const pkg of all) {
    if (!indegree.has(pkg)) indegree.set(pkg, 0);
    if (!dependents.has(pkg)) dependents.set(pkg, []);
  }

  for (const [pkg, requires] of Object.entries(deps)) {
    indegree.set(pkg, requires.length);
    for (const r of requires) {
      dependents.get(r)!.push(pkg);
    }
  }

  // Min-heap (lexicographically smallest) using a sorted insertion approach
  // For correctness with lex smallest, use a priority queue (min-heap)
  // Implement a simple min-heap
  const heap: string[] = [];

  const heapPush = (val: string) => {
    heap.push(val);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent] > heap[i]) {
        [heap[parent], heap[i]] = [heap[i], heap[parent]];
        i = parent;
      } else break;
    }
  };

  const heapPop = (): string => {
    const top = heap[0];
    const last = heap.pop()!;
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      while (true) {
        let smallest = i;
        const l = 2 * i + 1, r = 2 * i + 2;
        if (l < heap.length && heap[l] < heap[smallest]) smallest = l;
        if (r < heap.length && heap[r] < heap[smallest]) smallest = r;
        if (smallest === i) break;
        [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
        i = smallest;
      }
    }
    return top;
  };

  // Initialize heap with zero-indegree nodes
  for (const [pkg, deg] of indegree) {
    if (deg === 0) heapPush(pkg);
  }

  const result: string[] = [];

  while (heap.length > 0) {
    const pkg = heapPop();
    result.push(pkg);
    for (const dependent of dependents.get(pkg) ?? []) {
      const newDeg = indegree.get(dependent)! - 1;
      indegree.set(dependent, newDeg);
      if (newDeg === 0) heapPush(dependent);
    }
  }

  if (result.length !== all.size) {
    throw new Error("cycle detected in dependency graph");
  }

  return result;
}
