function parseCsvLine(line: string): string[] {
  const fields: string[] = [];
  let i = 0;

  while (i <= line.length) {
    if (i === line.length) {
      fields.push("");
      break;
    }

    if (line[i] === '"') {
      // Quoted field
      i++; // skip opening quote
      let field = "";
      while (true) {
        if (i >= line.length) {
          throw new Error("Unterminated quoted field");
        }
        if (line[i] === '"') {
          if (i + 1 < line.length && line[i + 1] === '"') {
            // Escaped quote
            field += '"';
            i += 2;
          } else {
            // Closing quote
            i++; // skip closing quote
            if (i < line.length && line[i] !== ',') {
              throw new Error(
                `Unexpected character '${line[i]}' after closing quote at position ${i}`
              );
            }
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }
      fields.push(field);
      if (i < line.length) {
        i++; // skip comma
      }
    } else {
      // Unquoted field
      const start = i;
      while (i < line.length && line[i] !== ',') {
        i++;
      }
      fields.push(line.slice(start, i));
      if (i < line.length) {
        i++; // skip comma
        if (i === line.length) {
          // Trailing comma means empty last field
          fields.push("");
        }
      }
    }
  }

  return fields;
}
