function compareSemver(a: string, b: string): -1 | 0 | 1 {
  function parse(v: string): { major: number; minor: number; patch: number; pre: string[] | null } {
    // Strip build metadata
    const plusIdx = v.indexOf('+');
    if (plusIdx !== -1) v = v.slice(0, plusIdx);

    const preIdx = v.indexOf('-');
    let core: string;
    let preStr: string | null = null;
    if (preIdx !== -1) {
      core = v.slice(0, preIdx);
      preStr = v.slice(preIdx + 1);
    } else {
      core = v;
    }

    const parts = core.split('.');
    if (parts.length !== 3) throw new Error(`Invalid semver: "${v}"`);

    function parseNum(s: string, field: string): number {
      if (!/^\d+$/.test(s)) throw new Error(`Invalid semver field "${field}": "${s}"`);
      if (s.length > 1 && s[0] === '0') throw new Error(`Leading zero in semver field "${field}": "${s}"`);
      return Number(s);
    }

    const major = parseNum(parts[0], 'major');
    const minor = parseNum(parts[1], 'minor');
    const patch = parseNum(parts[2], 'patch');

    let pre: string[] | null = null;
    if (preStr !== null) {
      if (preStr === '') throw new Error(`Empty pre-release: "${v}"`);
      pre = preStr.split('.');
      for (const id of pre) {
        if (id === '') throw new Error(`Empty pre-release identifier in: "${v}"`);
        if (/^\d+$/.test(id)) {
          if (id.length > 1 && id[0] === '0') throw new Error(`Leading zero in pre-release identifier: "${id}"`);
        } else {
          if (!/^[0-9A-Za-z-]+$/.test(id)) throw new Error(`Invalid pre-release identifier: "${id}"`);
        }
      }
    }

    return { major, minor, patch, pre };
  }

  const pa = parse(a);
  const pb = parse(b);

  function cmp(x: number, y: number): -1 | 0 | 1 {
    return x < y ? -1 : x > y ? 1 : 0;
  }

  const majorCmp = cmp(pa.major, pb.major);
  if (majorCmp !== 0) return majorCmp;

  const minorCmp = cmp(pa.minor, pb.minor);
  if (minorCmp !== 0) return minorCmp;

  const patchCmp = cmp(pa.patch, pb.patch);
  if (patchCmp !== 0) return patchCmp;

  // Pre-release precedence
  if (pa.pre === null && pb.pre === null) return 0;
  if (pa.pre === null && pb.pre !== null) return 1;
  if (pa.pre !== null && pb.pre === null) return -1;

  const preA = pa.pre!;
  const preB = pb.pre!;
  const len = Math.min(preA.length, preB.length);

  for (let i = 0; i < len; i++) {
    const idA = preA[i];
    const idB = preB[i];
    const aIsNum = /^\d+$/.test(idA);
    const bIsNum = /^\d+$/.test(idB);

    if (aIsNum && bIsNum) {
      const r = cmp(Number(idA), Number(idB));
      if (r !== 0) return r;
    } else if (aIsNum && !bIsNum) {
      return -1;
    } else if (!aIsNum && bIsNum) {
      return 1;
    } else {
      if (idA < idB) return -1;
      if (idA > idB) return 1;
    }
  }

  return cmp(preA.length, preB.length);
}
