function buildOrder(deps: Record<string, string[]>): string[] {
  // Collect all packages
  const allPackages = new Set<string>();
  for (const [pkg, pkgDeps] of Object.entries(deps)) {
    allPackages.add(pkg);
    for (const dep of pkgDeps) {
      allPackages.add(dep);
    }
  }

  // Build adjacency list and in-degree count
  const inDegree = new Map<string, number>();
  const graph = new Map<string, string[]>();

  for (const pkg of allPackages) {
    inDegree.set(pkg, 0);
    graph.set(pkg, []);
  }

  for (const [pkg, pkgDeps] of Object.entries(deps)) {
    for (const dep of pkgDeps) {
      // dep must come before pkg: edge dep -> pkg
      graph.get(dep)!.push(pkg);
      inDegree.set(pkg, inDegree.get(pkg)! + 1);
    }
  }

  // Kahn's algorithm with a min-heap (sorted array as priority queue)
  // Use lexicographically smallest by always picking the smallest available
  const available: string[] = [];
  for (const [pkg, degree] of inDegree) {
    if (degree === 0) {
      available.push(pkg);
    }
  }
  available.sort();

  const result: string[] = [];

  while (available.length > 0) {
    // Pick lexicographically smallest
    const pkg = available.shift()!;
    result.push(pkg);

    const neighbors = graph.get(pkg) ?? [];
    const newlyAvailable: string[] = [];
    for (const neighbor of neighbors) {
      const newDegree = inDegree.get(neighbor)! - 1;
      inDegree.set(neighbor, newDegree);
      if (newDegree === 0) {
        newlyAvailable.push(neighbor);
      }
    }

    // Insert new available packages in sorted order
    newlyAvailable.sort();
    // Merge into available (both sorted)
    let i = 0;
    for (const newPkg of newlyAvailable) {
      while (i < available.length && available[i] < newPkg) {
        i++;
      }
      available.splice(i, 0, newPkg);
      i++;
    }
  }

  if (result.length !== allPackages.size) {
    throw new Error("cycle detected in dependency graph");
  }

  return result;
}
